ALTER TABLE `notification_logs` MODIFY `channel` ENUM('EMAIL','PUSH','WHATSAPP','WEBHOOK') NOT NULL DEFAULT 'EMAIL';

CREATE TABLE `tenant_whatsapp_configs` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `active` BOOLEAN NOT NULL DEFAULT FALSE, `phone_number_id` VARCHAR(80) NOT NULL, `business_account_id` VARCHAR(80) NOT NULL, `encrypted_access_token` TEXT NOT NULL, `api_version` VARCHAR(16) NOT NULL DEFAULT 'v23.0', `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `tenant_whatsapp_configs_public_id_key` (`public_id`), UNIQUE INDEX `tenant_whatsapp_configs_tenant_id_key` (`tenant_id`), CONSTRAINT `tenant_whatsapp_configs_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `external_integrations` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `name` VARCHAR(120) NOT NULL, `endpoint` VARCHAR(2048) NOT NULL, `encrypted_secret` TEXT NULL, `events` JSON NOT NULL, `active` BOOLEAN NOT NULL DEFAULT FALSE, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `external_integrations_public_id_key` (`public_id`), UNIQUE INDEX `external_integrations_tenant_id_name_key` (`tenant_id`,`name`), INDEX `external_integrations_tenant_id_active_idx` (`tenant_id`,`active`), CONSTRAINT `external_integrations_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
